    "content": "<?xml version=\"1.0\" encoding=\"utf-8\"?>\n<resources>\n    <string name=\"app_name\">ZView</string>\n    <string name=\"app_tagline\">Document Scanner &amp; PDF Creator</string>\n    <string name=\"feedback_url\">https://zynor-view.web.app/</string>\n    <string name=\"scan_document\">Scan Document</string>\n    <string name=\"import_images\">Import Images</string>\n    <string name=\"recent_documents\">Recent Documents</string>\n    <string name=\"view_all_documents\">View All Documents</string>\n    <string name=\"personal_review_feedback\">Personal Review &amp; Feedback</string>\n    <string name=\"privacy_summary\">ZView processes and stores all scanned pages, image enhancements, and generated PDFs locally on your device. No account registration, tracking SDKs, or remote uploads are used.</string>\n</resources>\n"
